function err(e,retry){if(e&&e.code==='attempt_session_required'){ctx.sessionStale=true;paint('<p role="alert">다른 탭이나 기기에서 이 시험을 열었어요. 저장된 답안과 아직 전송하지 못한 별표는 보관됩니다. 여기서 계속하려면 회차를 다시 선택해 주세요.</p><button type="button" class="tool-btn" id="feClaimBack">회차 목록</button>');bind('#feClaimBack',function(){ctx.attemptToken=null;ctx.attemptRun=null;list();});return;}var msg=e&&e.code==='review_empty'?'이 회차에 저장된 선택오답이나 별표가 아직 없어요.':e&&e.code==='asset_unavailable'?'원본 시험지 준비가 아직 끝나지 않았어요.':e&&e.code==='schema_not_ready'?'시험 기록 저장 준비가 아직 끝나지 않았어요.':e&&e.status===404?'본인의 시험 기록을 찾을 수 없어요.':'정보를 불러오거나 저장하지 못했어요. 다시 확인해 주세요.';paint('<p role="alert">'+msg+'</p><button type="button" class="tool-btn" id="feRetry">다시 확인</button>');bind('#feRetry',retry||list);}
/* 요청 중 버튼을 끄고 다시 그리면 포커스가 BODY로 빠진다. CBT 안에서 시작한 요청만, 사용자가 CBT 밖으로 옮기지 않았을 때 같은 컨트롤(없거나 꺼졌으면 #feJump)로 돌려준다 */
function focusBack(from,want){if(!from||!valid())return;var a=root.document.activeElement;if(a&&a!==root.document.body&&!host.contains(a))return;var pick=function(sel){var e=sel&&host.querySelector(sel);return e&&!e.disabled?e:null;},t=pick(want);if(!t&&from.option)host.querySelectorAll('[data-option]').forEach(function(b){if(b.dataset.option===from.option&&!b.disabled)t=b;});t=t||(from.id&&pick('#'+from.id))||pick('#feJump')||pick('#feProblemList')||pick('#feResult')||pick('#feResume')||pick('#feStart');if(t)t.focus({preventScroll:true});}
function request(fn,then,retry,want,onFailure){if(!valid()||ctx.pending)return Promise.resolve();ctx.pending=true;var seq=++ctx.seq,owner=ctx.owner,a=root.document.activeElement,from=a&&a!==host&&host.contains(a)?{id:a.id,option:a.dataset&&a.dataset.option}:null;ctx.lastFocus=from;host.setAttribute('aria-busy','true');ctx.disabledControls=Array.from(host.querySelectorAll('button,select,input')).map(function(e){var state={element:e,disabled:e.disabled};e.disabled=true;return state;});return Promise.resolve().then(fn).then(function(d){if(!valid()||seq!==ctx.seq||current()!==owner)return;ctx.pending=false;host.removeAttribute('aria-busy');then(d);focusBack(from,want);},function(e){if(!valid()||seq!==ctx.seq)return;ctx.pending=false;if(current()!==owner||e.code==='session_changed'||e.status===401){login();return;}if(onFailure){host.removeAttribute('aria-busy');onFailure(e);focusBack(from,from&&from.id);}else{err(e,retry);focusBack(from,'#feRetry');}});}
function runPath(r){return(r.kind==='review'?'/reviews/':'/runs/')+r.id;}
function routeId(r){return(r.kind==='review'?'review-':'')+r.id;}
function raw(method,path,body){return Promise.resolve().then(function(){return api.cbt(method,'/api/v1/cbt'+path,body,{attemptToken:path.indexOf('/runs/')===0?ctx.attemptToken:null});});}
function call(method,path,body){return raw(method,path,body).then(function(d){return d&&d.run&&Array.isArray(d.items)&&d.run.status!=='ready'&&d.run.status!=='incomplete'?syncStars(d).then(function(){return d;}):d;});}
function pendingStarsKey(d){return 'hanq:cbt-stars-pending:v2:'+ctx.owner+':'+d.run.id;}
function storedStars(d,key){var v=null;try{v=JSON.parse(root.localStorage.getItem(key));}catch(e){}return v&&v.owner===ctx.owner&&v.run===d.run.id&&v.signature===signature(d)?v:null;}
function validStarResponse(d,v){return v&&v.signature===signature(d)&&Array.isArray(v.flags)&&v.flags.length===d.items.length&&v.flags.every(function(x){return typeof x==='boolean';});}
function starEpoch(d){var local=root.HanqLearningReset&&root.HanqLearningReset.cutoff(ctx.owner,'history')||0,remote=d&&d.serverStars&&Date.parse(d.serverStars.resetAt)||0,at=Math.max(local,remote);return at?new Date(at).toISOString():null;}
function sameStarEpoch(p,d){return (Date.parse(p&&p.resetAt)||0)===(Date.parse(starEpoch(d))||0);}
function archiveStars(d,p){try{var key=pendingStarsKey(d)+':archive:'+(root.crypto&&root.crypto.randomUUID?root.crypto.randomUUID():Date.now()+'-'+Math.random()),value=JSON.stringify(p);root.localStorage.setItem(key,value);return root.localStorage.getItem(key)===value;}catch(_){return false;}}
async function syncStars(d){
 if(d.run.kind!=='review'&&d.run.status==='active'&&(!ctx.attemptToken||ctx.attemptRun!==d.run.id))return;
 var owner=ctx.owner,path=runPath(d.run)+'/stars',pending=storedStars(d,pendingStarsKey(d))||d.pendingStarChanges;
 if(!pending&&ctx.data&&ctx.data.run.id===d.run.id&&ctx.data.pendingStarChanges&&ctx.data.pendingStarChanges.owner===owner&&ctx.data.pendingStarChanges.signature===signature(d))pending=ctx.data.pendingStarChanges;
 try{
  var server=await raw('GET',path);if(!validStarResponse(d,server))throw Error('invalid star response');d.serverStars=server;if(pending&&!sameStarEpoch(pending,d))pending=null;
  var legacy=storedStars(d,starsKey(d.run));
  if(!starEpoch(d)&&legacy&&Array.isArray(legacy.flags)&&legacy.flags.length===d.items.length&&legacy.flags.every(function(x){return typeof x==='boolean';})&&legacy.flags.some(Boolean))server=await raw('POST',path+'/import',{signature:signature(d),flags:legacy.flags});
  if(pending&&pending.changes){for(var pos of Object.keys(pending.changes)){if(!/^\d+$/.test(pos)||Number(pos)>=d.items.length||typeof pending.changes[pos]!=='boolean')continue;server=await raw('POST',path,{signature:signature(d),position:Number(pos),starred:pending.changes[pos],resetAt:pending.resetAt||null});}}
  if(!validStarResponse(d,server))throw Error('invalid star response');
  if(current()!==owner)throw {code:'session_changed'};
  d.serverStars=server;d.starSyncError=false;d.pendingStarChanges=null;if(pending&&pending.changes)Object.keys(pending.changes).forEach(function(p){delete pending.changes[p];});if(pending)try{root.localStorage.removeItem(pendingStarsKey(d));}catch(e){}
 }catch(e){if(e.status===401||e.code==='session_changed'||e.code==='attempt_session_required')throw e;d.starSyncError=true;d.pendingStarChanges=pending||null;}
}
async function migrateDeviceStars(){
 var owner=ctx.owner,prefix='hanq:cbt-stars:v1:'+owner+':',keys=[];
 for(var k=0;k<root.localStorage.length;k++){var key=root.localStorage.key(k);if(key&&key.indexOf(prefix)===0)keys.push(key);}
 for(var key of keys){var saved;try{saved=JSON.parse(root.localStorage.getItem(key));}catch(e){continue;}
  var id=key.slice(prefix.length);if(!/^[0-9a-f-]{36}$/.test(id)||!saved||saved.owner!==owner||saved.run!==id||typeof saved.signature!=='string'||!Array.isArray(saved.flags)||!saved.flags.every(function(x){return typeof x==='boolean';})||!saved.flags.some(Boolean))continue;
  var state;try{state=await raw('GET','/runs/'+id+'/stars');}catch(e){if(e.status===404)continue;throw e;}
  if(current()!==owner)throw {code:'session_changed'};
  if(state.signature!==saved.signature||!Array.isArray(state.flags)||state.flags.length!==saved.flags.length)continue;
  if(state.resetAt||(root.HanqLearningReset&&root.HanqLearningReset.cutoff(owner,'history')))continue;
  await raw('POST','/runs/'+id+'/stars/import',{signature:saved.signature,flags:saved.flags});
 }
}
