function runTable(runs){return '<div class="fe-runs-scroll" role="region" aria-label="내 시험 기록 · 좌우로 스크롤" tabindex="0"><table class="fe-runs-table"><caption>내 시험 기록</caption><thead><tr><th scope="col">회차</th><th scope="col">시험 점수</th><th scope="col">정답수 / 50</th><th scope="col">응시 일시</th><th scope="col">상태</th></tr></thead><tbody>'+(!runs.length?'<tr><td colspan="5">아직 시험 기록이 없어요.</td></tr>':runs.map(function(r){var score=r.status==='final'&&cbtScore(r.result)?r.result:null,at=r.startedAt||r.finalAt||null,date=new Date(at||''),when=at&&Number.isFinite(date.getTime())?new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short'}).format(date):at?'확인 필요':'시작 전',state=r.status==='final'?'완료':r.status==='ready'?'시작 전':r.paused?'일시정지':'진행 중',action=r.status==='final'?'결과 보기':r.status==='ready'?'시작하기':'이어서 풀기';return '<tr><td>제'+esc(r.round)+'회</td><td>'+(score?esc(score.score)+' / 100점':'—')+'</td><td>'+(score?esc(score.correct):'—')+' / 50</td><td><time datetime="'+esc(at||'')+'">'+esc(when)+'</time></td><td>'+state+'<br><button type="button" class="tool-btn" data-run="'+esc(r.id)+'">'+action+'</button></td></tr>';}).join(''))+'</tbody></table></div>';}

