function paperNumbers(value){
 var input=String(value).normalize('NFKC').trim();
 if(!input)return [];
 var pieces=input.replace(/,\s*$/,'').split(',');
 if(pieces.length>100)throw new Error('paper_numbers');
 var numbers=pieces.map(function(v){v=v.trim();if(!/^\d{1,2}$/.test(v)||+v<1||+v>50)throw new Error('paper_numbers');return +v;});
 return Array.from(new Set(numbers)).sort(function(a,b){return a-b;});
}
