async function paperRequestKey(owner,normalized){
 var prefix='hanq-paper-import-v1:',key=null,previous=null,id;
 try{
  var digest=await root.crypto.subtle.digest('SHA-256',new root.TextEncoder().encode(JSON.stringify([String(owner),normalized])));
  key=prefix+Array.from(new Uint8Array(digest),function(n){return n.toString(16).padStart(2,'0');}).join('');
  previous=JSON.parse(root.sessionStorage.getItem(key)||'null');
 }catch(_){}
 if(previous&&typeof previous.id==='string'&&/^[a-f0-9-]{36}$/i.test(previous.id))return {key:key,id:previous.id};
 id=root.crypto.randomUUID();
 if(key)try{root.sessionStorage.setItem(key,JSON.stringify({id:id}));}catch(_){}
 return {key:key,id:id};
}
